# Let me search all .json files for a 21x28 grid with right color counts
import os
import json

programs_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen/play/users/u011/system/state/workspace/programs"

def check_grid(fpath):
    try:
        with open(fpath, 'r') as f:
            data = json.load(f)
        if isinstance(data, list) and len(data) == 21 and all(len(r) == 28 for r in data):
            colors = Counter(x for row in data for x in row)
            non_zero = {c: cnt for c, cnt in colors.items() if c != 0}
            least = min(non_zero.keys(), key=lambda c: non_zero[c])
            least_count = non_zero[least]
            return fpath, least, least_count, dict(colors)
    except:
        return None

# Find all JSON files
json_files = [f for f in os.listdir(programs_dir) if f.endswith('.json')]
valid_grids = {}
for jf in json_files:
    result = check_grid(os.path.join(programs_dir, jf))
    if result:
        print(f"{jf}: least={result[1]}, count={result[2]}")

# Also check for grids with expected color pattern (0 as bg, and a seed color with small count)

with open("/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen/play/users/u011/system/state/workspace/programs/task-770f2daf.json", 'r') as f:
    demos = json.load(f)

print(f"Type: {type(demos)}, Length: {len(demos)}")

for i, d in enumerate(demos):
    print(f"\nDemo {i}:")
    print(f"  Keys: {d.keys()}")
    if isinstance(d, dict):
        # Try to extract input/output
        for key, val in d.items():
            if isinstance(val, list) and len(val) > 30:
                print(f"  {key}: rows={len(val)}")
                if len(val)>0 and isinstance(val[0], list):
                    colors = Counter(x for row in val for x in row)
                    print(f"    Colors: {dict(colors)}")

